def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    ratio = item / np.maximum(bins, 1e-9)
    return np.where(remaining < 0, -np.inf, ratio + (remaining / np.maximum(bins, 1e-9)))

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    valid = remaining >= 0
    used_ratio = (bins - remaining) / np.maximum(bins, 1e-9)
    score = np.exp(used_ratio) - (1.0 / np.maximum(remaining, 1e-9) ** 2)
    return np.where(valid, score, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining < 0, -np.inf, -np.abs(remaining - item) / np.maximum(bins, 1e-9))
